-- Smart APS demo seed (M1): materials / BOM / resources / calendar / routing / orders
-- Generated from projects/smart-aps-agent/scripts/seed-m1-demo.ps1; idempotent (fixed UUID cleanup + insert).
-- Usage: docker compose -f deploy/gz-api/docker-compose.yml exec -T aps-postgres psql -U aps -d aps < deploy/gz-api/aps-seed-m1.sql
BEGIN;
-- 1) constraint_justification rows that point at demo task ids
DELETE FROM constraint_justification cj
WHERE cj.tenant_id = '00000000-0000-0000-0000-000000000001'
  AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(cj.implicated_facts) AS fact
      WHERE (fact ->> 'id') ~ '^[0-9]+$'
        AND (fact ->> 'id')::bigint IN (
            SELECT t.id FROM task t
            WHERE t.tenant_id = '00000000-0000-0000-0000-000000000001'
              AND t.order_id IN ('d0000000-0000-0000-0000-000000000701','d0000000-0000-0000-0000-000000000702','d0000000-0000-0000-0000-000000000703','d0000000-0000-0000-0000-000000000704','d0000000-0000-0000-0000-000000000705','d0000000-0000-0000-0000-000000000706','d0000000-0000-0000-0000-000000000707','d0000000-0000-0000-0000-000000000708','d0000000-0000-0000-0000-000000000709')
        )
  );
-- 2) demo tasks and orders (fixed UUID list, never a code prefix)
DELETE FROM task WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND order_id IN ('d0000000-0000-0000-0000-000000000701','d0000000-0000-0000-0000-000000000702','d0000000-0000-0000-0000-000000000703','d0000000-0000-0000-0000-000000000704','d0000000-0000-0000-0000-000000000705','d0000000-0000-0000-0000-000000000706','d0000000-0000-0000-0000-000000000707','d0000000-0000-0000-0000-000000000708','d0000000-0000-0000-0000-000000000709');
DELETE FROM orders WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND id IN ('d0000000-0000-0000-0000-000000000701','d0000000-0000-0000-0000-000000000702','d0000000-0000-0000-0000-000000000703','d0000000-0000-0000-0000-000000000704','d0000000-0000-0000-0000-000000000705','d0000000-0000-0000-0000-000000000706','d0000000-0000-0000-0000-000000000707','d0000000-0000-0000-0000-000000000708','d0000000-0000-0000-0000-000000000709');
-- 3) process graph (fixed routing / node / edge ids)
DELETE FROM routing_edge WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND routing_id = 'd0000000-0000-0000-0000-000000000501';
DELETE FROM routing_node WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND routing_id = 'd0000000-0000-0000-0000-000000000501';
DELETE FROM routing WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND id = 'd0000000-0000-0000-0000-000000000501';
-- 4) BOM (fixed ids)
DELETE FROM bom_item WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND bom_id IN ('d0000000-0000-0000-0000-000000000601','d0000000-0000-0000-0000-000000000602');
DELETE FROM bom WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND id IN ('d0000000-0000-0000-0000-000000000601','d0000000-0000-0000-0000-000000000602');
-- 5) templates, resources, calendar, materials (fixed ids)
DELETE FROM operation_template WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND id IN ('d0000000-0000-0000-0000-000000000401','d0000000-0000-0000-0000-000000000402','d0000000-0000-0000-0000-000000000403','d0000000-0000-0000-0000-000000000404');
DELETE FROM resource WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND id IN ('d0000000-0000-0000-0000-000000000301','d0000000-0000-0000-0000-000000000302','d0000000-0000-0000-0000-000000000303','d0000000-0000-0000-0000-000000000304','d0000000-0000-0000-0000-000000000305','d0000000-0000-0000-0000-000000000306');
DELETE FROM calendar WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND id = 'd0000000-0000-0000-0000-000000000201';
DELETE FROM material WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND id IN ('d0000000-0000-0000-0000-000000000101','d0000000-0000-0000-0000-000000000102','d0000000-0000-0000-0000-000000000103','d0000000-0000-0000-0000-000000000104','d0000000-0000-0000-0000-000000000105');
-- 6) demo strategy and its solve tasks
DELETE FROM solve_task WHERE tenant_id = '00000000-0000-0000-0000-000000000001' AND strategy_id = 'd0000000-0000-0000-0000-000000000801';
DELETE FROM strategy WHERE id = 'd0000000-0000-0000-0000-000000000801';
COMMIT;

